package io.aetheris.orchestrator.trading;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="aetheris_paper_positions",uniqueConstraints=@UniqueConstraint(columnNames="signalId")) public class PaperPositionEntity {@Id private UUID id;@Column(nullable=false) private UUID signalId;@Column(nullable=false,length=40) private String symbol;@Enumerated(EnumType.STRING) @Column(nullable=false,length=16) private TradeSide side;private double entryPrice;private double quantity;private double notional;private int leverage;private double stopLoss;private double tp1;private double tp2;private double tp3;@Enumerated(EnumType.STRING) @Column(nullable=false,length=16) private PaperPositionStatus status;@Column(nullable=false) private Instant openedAt;private Instant closedAt;private double exitPrice;private double realizedPnl;protected PaperPositionEntity(){}public PaperPositionEntity(UUID id,TradeSignalEntity s,double fill,double qty){this.id=id;this.signalId=s.getId();this.symbol=s.getSymbol();this.side=s.getSide();this.entryPrice=fill;this.quantity=qty;this.notional=fill*qty;this.leverage=s.getLeverage();this.stopLoss=s.getStopLoss();this.tp1=s.getTakeProfit1();this.tp2=s.getTakeProfit2();this.tp3=s.getTakeProfit3();this.status=PaperPositionStatus.OPEN;this.openedAt=Instant.now();}public double close(double price){if(status!=PaperPositionStatus.OPEN)throw new IllegalStateException("Position is not open");this.exitPrice=price;this.realizedPnl=(side==TradeSide.LONG?price-entryPrice:entryPrice-price)*quantity;this.status=PaperPositionStatus.CLOSED;this.closedAt=Instant.now();return realizedPnl;}public UUID getId(){return id;}public UUID getSignalId(){return signalId;}public String getSymbol(){return symbol;}public TradeSide getSide(){return side;}public double getEntryPrice(){return entryPrice;}public double getQuantity(){return quantity;}public double getNotional(){return notional;}public int getLeverage(){return leverage;}public double getStopLoss(){return stopLoss;}public double getTp1(){return tp1;}public double getTp2(){return tp2;}public double getTp3(){return tp3;}public PaperPositionStatus getStatus(){return status;}public Instant getOpenedAt(){return openedAt;}public Instant getClosedAt(){return closedAt;}public double getExitPrice(){return exitPrice;}public double getRealizedPnl(){return realizedPnl;}}
